const msg = ($input.first().json.mensaje || '').toString().toLowerCase();
const convId = $input.first().json.conversacion_id || '';
const usuario = $input.first().json.usuario_id || null;

// Intenciones simples (ejemplo). Reemplaza/añade las tuyas.
let intencion = 'GENERAL';
let respuesta = '';

if (msg.includes('mis citas') || msg.includes('mis proximas')) {
  intencion = 'MIS_CITAS';
  respuesta = 'Para ver sus citas, inicie sesion y consulte "Mis citas". Si ya esta logueado, le listo sus proximas citas.';
} else if (msg.includes('horario') || msg.includes('hora de atencion')) {
  intencion = 'HORARIOS';
  respuesta = 'La atencion es de lunes a viernes. Consulte la disponibilidad por especialidad en "Disponibilidad horaria" para ver los cupos libres.';
} else if (msg.includes('cancelar') || msg.includes('reprogramar')) {
  intencion = 'CAMBIOS';
  respuesta = 'Puede reprogramar o cancelar sus citas desde "Mis citas", con al menos 24 horas de anticipacion.';
} else if (msg.includes('hola') || msg.includes('buenos')) {
  intencion = 'SALUDO';
  respuesta = 'Hola, soy el asistente de la Clinica Vida Salud. Puedo ayudarle con horarios, sus citas y dudas generales.';
} else {
  intencion = 'SIN_RESPUESTA';
  respuesta = 'No tengo una respuesta para esa consulta. Se la paso al personal para que la revise.';
}

// (Opcional) Llamar a un LLM: descomenta y configura la credencial HTTP en n8n.
// const r = await this.helpers.httpRequest({ method: 'POST', url: 'https://api.openai.com/v1/chat/completions', headers: { Authorization: 'Bearer ' + $env.OPENAI_API_KEY, 'Content-Type': 'application/json' }, body: { model: 'gpt-4o-mini', messages: [{role:'user', content: msg}] }, json: true });
// respuesta = r.choices?.[0]?.message?.content || respuesta;

return [{ json: { respuesta, intencion, conversacion_id: convId } }];
